entries[91075] = { ["name"] = "Rachsüchtiger Irrwisch", ["text"] = "45 Meter Reichweite\nSofort\nVerursacht 15 Sek. lang alle 3 Sek. 2 Naturschaden, mit einer Chance von 100%, sich auf einen zufälligen nahen Feind auszubreiten, wann immer Schaden verursacht wird." }
