entries[91205] = { ["name"] = "Alphastrahlen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht bis Abbruch lang alle 0.5 Sek. 0 Schattenschaden." }
entries[91209] = { ["name"] = "Krug mit Jormungarblut", ["text"] = "Wirken in 2 sek. 5\nDieses Glasbehältnis ist mit dem eiskalten, ätzenden Blut von Nordends großen Jormungarwürmern gefüllt. Legenden zufolge nutzten die Neruber die Jormungar, um die unterirdischen Passagen und Grotten zu schaffen, in denen die beeindruckenden Städte Azjol-Nerubs erbaut waren.\nKrug mit Jormungarblut\nWird beim Aufheben gebunden" }
entries[91211] = { ["name"] = "Zerknittertes Fahnenband des Wesirs", ["text"] = "Wirken in 2 sek. 5\nDieses seltsame Objekt ist anscheinend Teil einer Schriftrolle von immensen Ausmaßen. Sie besteht aus mit Papyrus beklebtem Leder und ist in blutroter Tinte mit Diagrammen und nerubischer Schrift bedeckt.\n\n\"Unhhh-tikk-a-shisss. Kka shir. Na-l bkah a-shisss. Kreesh kik ik ta. Sohk-a tik hiss a-k-k-k.\"\nZerknittertes Fahnenband des Wesirs\nWird beim Aufheben gebunden" }
entries[91212] = { ["name"] = "Anstürmen", ["text"] = "45 Meter Reichweite\nSofort 3 sek. Abklingzeit\nStürmt auf einen Gegner zu, fügt ihm sowie seinen nahen Verbündeten 14 Schaden zu und stößt alle betroffenen Ziele zurück." }
entries[91213] = { ["name"] = "Schmettern", ["text"] = "Sofort\nFügt Gegnern im Umkreis von 10 Metern 1312 körperlichen Schaden zu." }
entries[91214] = { ["name"] = "Segen des Alten Gottes", ["text"] = "Wirken in 2 sek. 15\nPwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal. Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal. Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal.\nSegen des Alten Gottes\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erhaltet 20 Sek. lang den Segen des Alten Gottes. (10 Min Abklingzeit)" }
entries[91215] = { ["name"] = "Puzzlebox des Yogg-Saron", ["text"] = "Wirken in 2 sek. 15\nDiese kleine Box hat bewegliche Oberflächen, verschiebbare Angeln und versteckte Scharniere. Dessen ungeachtet scheint es Euch unmöglich, die Box so zu manipulieren, dass sie sich öffnet und ihren Inhalt preisgibt. Es ist schwierig, auch nur den Versuch zu wagen, da das dunkle Artefakt Euch beständig einflüstert, \"Es WAR deine Schuld. Es WAR deine Schuld. Es WAR deine Schuld. Es WAR deine Schuld.\"\nPuzzlebox des Yogg-Saron\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Macht einen vergeblichen Versuch, die Puzzlebox zu öffnen. (1 Min Abklingzeit)\n\"Extrem schwer zu öffnen.\"" }
entries[91216] = { ["name"] = "Säureregen" }
entries[91218] = { ["name"] = "Geistererscheinung" }
entries[91219] = { ["name"] = "Silberkris des Korl", ["text"] = "Wirken in 2 sek. 5\nMit dem warmen Herzblut des Schreckenswyrms Kaldrigos graviert.\nSilberkris des Korl\nWird beim Aufheben gebunden" }
entries[91220] = { ["name"] = "Erschauerndes Gebrüll", ["text"] = "Wirken in 1 sek.\nEin lautes, markerschütterndes Gebrüll erhallt und versetzt alle in der Nähe befindlichen Feinden 3 Sek. lang in Angst. Erlittener Schaden hebt den Effekt auf." }
entries[91221] = { ["name"] = "Kriegsschlägel von Brandauge", ["text"] = "Wirken in 2 sek. 5\nEisenthan Brandauge liebte den Kampf und für seine zwei großen Kriegshämmer war er weitbekannt. Ihr habt einen von ihnen wieder zusammengefügt, doch seine Magie hat sich schon lang verflüchtigt. Das heißt also, dass sich der zweite auch noch irgendwo befinden muss und vielleicht noch intakt ist.\nKriegsschlägel von Brandauge\nWird beim Aufheben gebunden" }
entries[91222] = { ["name"] = "Erschüttert" }
entries[91223] = { ["name"] = "Stachelverbundstulpen von Zorneshammer", ["text"] = "Wirken in 2 sek. 5\nZorneshammer war einer der mächtigsten Generäle des Schwarzfels. Sein Wappen, das einen flammenschlagenden Amboss zeigt, ist selbst heute noch auf Schilden und Wappenröcken im Schwarzfelz zu sehen. Auch wenn er selbst nicht mehr lebt, tragen noch viele Soldaten der Dunkeleisenzwerge stolz seinen Namen.\nStachelverbundstulpen von Zorneshammer\nWird beim Aufheben gebunden" }
entries[91224] = { ["name"] = "Wort von Kaiserin Zoe", ["text"] = "Wirken in 2 sek. 5\nDas Wort und der Schwur von Kaiserin Zoe waren einst ein Paar machtvoller magischer Ringe. Der Ring, den Ihr gefunden habt, ist das Wort - leider verlor dieser Ring seine magischen Eigenschaften, als er brach. Der Schwur ist weiterhin verloren, jedoch ist er möglicherweise noch intakt. Die Kaiserin war eine wenig bekannte Herrscherin der Dunkeleisenzwerge, von denen viele ihr Leben an Zoes Faszination für Drachen verloren. Der Versuch, Dracheneier oder Jungtiere zu stehlen, endete oft tödlich.\nWort von Kaiserin Zoe\nWird beim Aufheben gebunden" }
entries[91225] = { ["name"] = "Szepter der Bronzebart", ["text"] = "Wirken in 2 sek. 5\nDie Bronzebarts sind sowohl ein Zwergenklan als auch die Herrscherfamilie der Zwerge. Die Könige des Hohen Sitzes haben während ihrer Amtszeit viele Szepter abgenutzt. Einer Tradition folgend würde der König seinen ranghöchsten Beratern und Verbündeten sein Szepter für einen Tag übergeben. Das waren harte Tage für die Szepter, die durch Tavernen geschliffen, von Klippen geschleudert und als Troggknüppel verwendet wurden.\nSzepter der Bronzebart\nWird beim Aufheben gebunden" }
entries[91226] = { ["name"] = "Die Tochter des Gastwirts", ["text"] = "Wirken in 2 sek. 15\nDer Legende nach führte Bryher Steinhüter eine florierende Taverne in der Nähe von Loch Modan. Seine Tochter Keelin reiste weit herum und entwickelte schließlich einen gewissen Leumund, der ihren Vater beschämte. Bryher schloss einen Handel mit einem gnomischen Hexenmeister ab - er sollte es bewerkstelligen, dass die Tochter immer in der Nähe ihres Zuhauses bleiben würde. Daraufhin verwandelte der Hexenmeister Keelin in einen Ruhestein, damit sie ihr Weg stets in das Gasthaus zurückführen würde.\nDie Tochter des Gastwirts\nWird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern." }
entries[91227] = { ["name"] = "Stab des Zaubererthans Thaurissan", ["text"] = "Wirken in 2 sek. 15\nZaubererthan Thaurissan war während des Kriegs der Drei Hämmer der Anführer der Dunkeleisenzwerge. Als er Eisenschmiede an den Bronzebartklan verlor, zog sich Thaurissan in das Rotkammgebirge zurück und gründete eine Stadt, die seinen Namen trug. In dem verzweifelten Versuch, seine Feinde zu bezwingen, beschwor Thaurissan versehentlich den Halbgott Ragnaros, was sowohl zum sofortige Tode des Zaubererthans als auch zum Entstehen der vulkanischen Aktivität des Schwarzfels führte.\nStab des Zaubererthans Thaurissan\nWird an Kriegsmeute gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\n32" }
