entries[91760] = { ["name"] = "Transformation durchleben", ["text"] = "Sofort\nDurchlebt 2 Min. lang die Transformation." }
entries[91761] = { ["name"] = "Knochen der Transformation", ["text"] = "Wirken in 2 sek. 15\nAls der erste Brunnen der Ewigkeit implodierte, sank das kulturelle Zentrum der Nachtelfen auf den Meeresgrund. Um ihrem sicheren Tod zu entfliehen, ging Königin Azshara einen Pakt mit einer größeren Macht ein, wahrscheinlich einem Alten Gott oder einem Elementar. Im Resultat wurden die überlebenden Hochgeborenen von einem Fluch befallen, der sie zu pervertierten, schlangenartigen Kreaturen transfomierte, die heute als Naga bekannt sind.\nKnochen der Transformation\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Durchlebt 2 Min. lang die Transformation. (10 Min Abklingzeit)" }
entries[91762] = { ["name"] = "Collier der einhundert Magi", ["text"] = "Wirken in 2 sek. 5\nWährend der Trollkriege wurden die Elfen von Quel'Thalas beinahe von den Amani bezwungen. In ihrer Verzweiflung lehrten die Elfen Menschen aus Arathor die Arkanmagie. Sie nahmen nur einhundert Schüler - die minimale Zahl, um die Trolle zu bezwingen. Die Menschen waren plumpe Magier, die jedoch eine natürliche Begabung für Magie hatten.\nCollier der einhundert Magi\nWird beim Aufheben gebunden" }
