entries[91766] = { ["name"] = "Silberner Schriftrollenbehälter", ["text"] = "Wirken in 2 sek. 5\nDieser elfische Schrifrollenbehälter ist zwar reich verziert, doch ist es die Nachricht, die von größerem Interesse ist: \"Pyramond, du wirst unter keinen Umständen Zeit mit diesem Weibsbild verbringen. Deine Mutter und ich verbieten es. Sie ist ganz eindeutig unter deiner Würde.\"\nSilberner Schriftrollenbehälter\nWird beim Aufheben gebunden" }
entries[91767] = { ["name"] = "See Invis 13" }
entries[91768] = { ["name"] = "Summon Agatha" }
entries[91769] = { ["name"] = "Schattensichel", ["text"] = "Wirken in 2 sek. 5\nDiese Art kreisrunder Klingen wird seit Ewigkeiten von nachtelfischen Wachen bevorzugt. Eine bekannte Trägerin dieses Waffentyps war Maiev Schattensang, jedoch werden die Klingen auch heute noch von Nachtelfen genutzt, beispielsweise den Tiefenwächtern der Grabhügel des Hyjal. Es ist wahrscheinlich, dass die von Euch gefundene Waffe magische Qualitäten aufwies, bevor sie in so viele Fragmente zerbrach.\nSchattensichel\nWird beim Aufheben gebunden" }
entries[91770] = { ["name"] = "Signal Flare 01" }
entries[91771] = { ["name"] = "Irrwischgestalt", ["text"] = "Sofort\nNehmt 2 Min. lang eine Irrwischgestalt an." }
entries[91773] = { ["name"] = "Irrwischamulett", ["text"] = "Wirken in 2 sek. 15\nIrrwische sind Naturgeister, angeblich verstorbene Nachtelfen. Sie haben eine starke Verbindung zu den Wäldern ihrer Heimat sowie den Nachtelfen im allgemeinen und führen für sie dienliche Dinge aus, wie die Konstruktion oder Reparatur von Bauten und die Verteidigung elfischer Gemeinschaften. Viele Irrwische opferten sich am Ende des Dritten Krieges, um Archimondes Zerstörung herbeizuführen, dadurch gibt es heutzutage weniger Irrwische, als einst.\nIrrwischamulett\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nehmt 2 Min. lang eine Irrwischgestalt an. (10 Min Abklingzeit)" }
entries[91774] = { ["name"] = "Signal Flare 01 Kill Credit" }
entries[91775] = { ["name"] = "Sandburg", ["text"] = "Wirken in 2 sek. 5\nDas ist eine kleine, rechteckige Festung aus Sand. Die Form der Türme und das Sonnenmotiv deuten auf Architektur der Tol'vir hin, eine entsprechende Festung in realem Maßstab habt Ihr jedoch noch nicht in Uldum gesehen. Das Objekt ist tatsächlich aus Sand, nicht Sandstein und Ihr seid Euch nicht sicher, wovon es zusammengehalten wird.\nSandburg\nWird beim Aufheben gebunden" }
entries[91776] = { ["name"] = "Klaue", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nSchlägt mit der Klaue nach dem Gegner und fügt ihm [0.54 * (Angriffskraft * 0.3) * (1 + Vielseitigkeit) * 1 ] körperlichen Schaden zu." }
entries[91777] = { ["name"] = "Tirisfal Guardian Aura" }
entries[91778] = { ["name"] = "Klauenfeger", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nSchlägt mit deformierten Klauen nach dem Ziel, die ihm und Gegnern in der Nähe [0.54 * (Angriffskraft * 0.15) * (1 + Vielseitigkeit) * 3 * 1 ] Schattenschaden zufügen." }
entries[91779] = { ["name"] = "Katzenstatuette mit Smaragdaugen", ["text"] = "Wirken in 2 sek. 5\nDie kleine tönerne Katze ist in lebensechter Position und mit regem Ausdruck dargestellt. Auf der Unterseite steht geschrieben, 'In Erinnerung an Chalyx, geliebtes Haustier des Imperators Ninjter.'\nKatzenstatuette mit Smaragdaugen\nWird beim Aufheben gebunden" }
entries[91780] = { ["name"] = "Skarabäushalskette aus Speckstein", ["text"] = "Wirken in 2 sek. 5\n'Imperator Ninjter am Tage seiner Thronbesteigung überreicht. Wir erwarten unter seiner Herrschaft nur Größe.'\nSkarabäushalskette aus Speckstein\nWird beim Aufheben gebunden" }
entries[91781] = { ["name"] = "Signal Flare 02" }
entries[91782] = { ["name"] = "Winziges Oasenmosaik", ["text"] = "Wirken in 2 sek. 5\nDieses kleine Kunstwerk habt Ihr aus seinen vielen kleinen verstreuten Tonkacheln wieder zusammengesetzt, seine satten Farben leuchten Euch türkiswasserblau, palmengrün und sandgelb entgegen.\n\n\"Unsere Hoffnung und Gebete für Imperator Ninjter, möge er der Hungersnot ein Ende setzen und den Ruhm der Ramkahen erneuern!\"\nWinziges Oasenmosaik\nWird beim Aufheben gebunden" }
entries[91783] = { ["name"] = "Signal Flare 03" }
entries[91784] = { ["name"] = "Signal Flare 02 Kill Credit" }
entries[91785] = { ["name"] = "Graviertes Krummsäbelheft", ["text"] = "Wirken in 2 sek. 5\nDieser Krummsäbel scheint eher Zierrat denn eine echte Waffe gewesen zu sein. Die Klinge endet nach nur einer Handbreite und scheint nie im Kampf genutzt worden zu sein. Ein Spruchband umringt den Schwertknauf und zieht sich dann auf das Heft weiter, es besagt: 'Möge Imperator Ninjter uns zum Sieg führen! Kadesh! Osadi! Satekh!'\nGraviertes Krummsäbelheft\nWird beim Aufheben gebunden" }
entries[91786] = { ["name"] = "Ziel würgen", ["text"] = "25 Meter Reichweite\nSofort\nGreift nach einem Passagier und zieht ihn hinein." }
entries[91787] = { ["name"] = "Flintlockes Sprengstoff platzieren", ["text"] = "Wirken in 1 sek.\nPlatziert Flintlockes Sprengstoff im Inneren des Himmelsreißers." }
entries[91788] = { ["name"] = "Kanonenkugel", ["text"] = "70 Meter Reichweite\nWirken in 1 sek.\nFeuert eine Kanonenkugel auf den Gegner ab, verursacht schweren Schaden und betäubt ihn." }
entries[91790] = { ["name"] = "Kanope", ["text"] = "Wirken in 2 sek. 5\nDieses Gefäß enthält die versteinerten inneren Organe von Imperator Ninjter. Offenbar starb er nur wenige Jahre, nachdem er seine vom Volk voller Hoffnung erwartete Herrschaft antrat.\nWird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[91791] = { ["name"] = "Würgen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht pro Sekunde 10% Schaden." }
entries[91792] = { ["name"] = "Skizze eines Wüstenpalastes", ["text"] = "Wirken in 2 sek. 5\nDies ist ein Bauplan und anscheinend träumte der Architekt in sehr großem Maßstab. Euch ist kein Gebäude dieser Art im heutigen Uldum bekannt, vermutlich ist dieser Palast also niemals erbaut worden.\n\n\"In Auftrag gegeben für Imperator Ninjter.\"\nSkizze eines Wüstenpalastes\nWird beim Aufheben gebunden" }
entries[91793] = { ["name"] = "Franclorn Schmiedevaters Pfeife", ["text"] = "Wirken in 2 sek. 5\nSchmiedevater war ein gefeierter Architekt des Dunkeleisenklans. Er beaufsichtigte, unter anderem, die Erbauung des Steinwerkdamms und eines Großteils der Schwarzfelstiefen. Es heißt, sein Geist geht noch immer im Schwarzfels um.\nFranclorn Schmiedevaters Pfeife\nWird beim Aufheben gebunden" }
