entries[91800] = { ["name"] = "Nagen", ["text"] = "Nahkampfreichweite\nSofort 1.5 min Abklingzeit\nBeißt und reißt an den Extremitäten des Ziels, fügt ihm Schaden zu und betäubt es für 1 Sek." }
entries[91801] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 120% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sek. lang um 25%." }
