entries[92137] = { ["name"] = "Eiskaltes Händchen", ["text"] = "Wirken in 2 sek. 15\nEine Legende der Tol'vir erzählt von einem bösen Dschinn, den die Ramkahen zerstören wollten. In dem Versuch, seinen eigenen Tod zu verhindern, ließ der Dschinn seinen Geist in den Körper eines Affen übergehen. Er wurde während des Transfers getötet, und nur ein Teil seiner Essenz war übertragen worden - gerade genug, um von der Hand des Affen Besitz zu ergreifen.\nEiskaltes Händchen\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer eiskaltes Händchen beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[92138] = { ["name"] = "Summon Goldrinn" }
entries[92139] = { ["name"] = "Stab von Ammunae", ["text"] = "Wirken in 2 sek. 15\nAmmunae ist einer der Wächter der Hallen des Ursprungs. Wie auch die anderen Konstrukte in den Hallen, wurde Ammunae erschaffen, um den Mechanismus zu bewachen, der zum Zurücksetzen allen Lebens in Azeroth befähigt war. Jeder der Wächter hat einen eigenen Einflussbereich. Isiset steht der Magie vor, Ammunae dem Leben, Setesh dem Chaos und Rajh der Sonne.\nStab von Ammunae\nWird an Kriegsmeute gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n+ 4 Vielseitigkeit\nHaltbarkeit 120 / 120\n32\n\"Achusenmen osadi djahi kahun Ammunae\"" }
